flags.typeql:
match
$q isa question, has created_at $ca, has favorites $f;
$ca >= 2020-01-01T00:00:00Z;
$ca < 2021-01-01T00:00:00Z;
sort $f desc;
limit 5;
fetch {
  "title": $q.title,
  "favorites": $f,
  "link": $q.link,
  "createdAt": $ca
};

with fun max_reputation() -> integer :
    match $u isa user, has reputation $r;
    return max($r);
match
    $u isa user, has reputation $rep;
    $rep == max_reputation();
    asked (asker: $u, asked_question: $q);
    $q has created_at $ca;
sort $ca desc;
limit 3;
fetch {
    "title": $q.title,
    "text": $q.text,
    "link": $q.link,
    "createdAt": $q.created_at
};

match
$u isa user;
asked (asker: $u, asked_question: $q);
$q isa question, has answered false, has up_votes $uv;
$uv > 0;
not {
  asked (asker: $u, asked_question: $q2);
  $q2 has answered true;
};
reduce $count = count($q) groupby $u;
sort $count desc;
limit 3;
fetch {
  "display_name": $u.display_name,
  "link": $u.user_link,
  "reputation": $u.reputation
};

with fun max_rep() -> integer :
    match $u isa user, has reputation $r;
    return max($r);
match
$u isa user, has reputation $rep;
let $max = max_rep();
$rep == $max;
asked (asker: $u, asked_question: $q);
$q has created_at $ca;
sort $ca asc;
limit 3;
fetch {
    "title": $q.title,
    "link": $q.link,
    "createdAt": $ca
};

with fun max_fav($u: user) -> integer:
  match
    asked (asker: $u, asked_question: $q);
    $q has favorites $f;
  return max($f);
with fun min_fav($u: user) -> integer:
  match
    asked (asker: $u, asked_question: $q);
    $q has favorites $f;
  return min($f);
match
  $u isa user;
let $max = max_fav($u);
let $min = min_fav($u);
let $variation = $max - $min;
sort $variation desc;
limit 3;
fetch {
  "user": $u.display_name,
  "favoritesVariation": $variation
};

